tool_calls:
mkdir -p /lib
cat > /lib/utils.sh <<'EOF'
to_upper() {
    tr '[:lower:]' '[:upper:]'
}

count_lines() {
    wc -l < "$1"
}

file_size() {
    wc -c < "$1"
}
EOF
source /lib/utils.sh
printf 'to_upper: '
printf '%s\n' 'hello world' | to_upper
printf 'count_lines: '
count_lines /data/sample.txt
printf 'file_size: '
file_size /data/sample.txt

